import {
  Meter,
  MeterIndicator,
  MeterLabel,
  MeterTrack,
  MeterValue,
} from "@/registry/erbium/ui/meter";

export default function MeterDemo() {
  return (
    <Meter value={24} className="w-72">
      <MeterLabel>Storage used</MeterLabel>
      <MeterValue />
      <MeterTrack>
        <MeterIndicator />
      </MeterTrack>
    </Meter>
  );
}

// Generated from the Erbium showcase catalog and shared Markdown.
import { ShowcaseProviders, ShowcaseSurface } from "../preview";
import type { Meta, StoryObj } from "@storybook/react";

import { Meter } from "@/registry/erbium/ui/meter";

import PlaygroundExample from "./variants/playground";

const PlaygroundSource = "import { Meter, MeterIndicator, MeterTrack } from \"@/registry/erbium/ui/meter\";\nimport type * as React from \"react\";\n\nconst Example = (args: React.ComponentProps<typeof Meter>) => (\n  <Meter {...args} className=\"w-72\" aria-label=\"Storage used\">\n    <MeterTrack>\n      <MeterIndicator />\n    </MeterTrack>\n  </Meter>\n);\n\nexport default Example;\n";

import OverviewExample from "./variants/overview";

const OverviewSource = "import Demo from \"../examples/meter-demo\";\n\nconst Example = () => <Demo />;\n\nexport default Example;\n";

import RangeExample from "./variants/range";

const RangeSource = "import {\n  Meter,\n  MeterIndicator,\n  MeterLabel,\n  MeterTrack,\n  MeterValue,\n} from \"@/registry/erbium/ui/meter\";\n\nconst Example = () => (\n  <Meter value={72} min={0} max={100} format={{ style: \"unit\", unit: \"percent\" }} className=\"w-72\">\n    <MeterLabel>Battery</MeterLabel>\n    <MeterValue />\n    <MeterTrack>\n      <MeterIndicator />\n    </MeterTrack>\n  </Meter>\n);\n\nexport default Example;\n";

const meta = {
  component: Meter,
  tags: ["autodocs"],
  parameters: {
    layout: "centered",
    docs: {
      description: {
        component: "## Usage\n\nShows a scalar value within a known range, such as disk usage or a score. Built on Base UI's `Meter`, which exposes `role=\"meter\"` with the value, min and max. For work moving toward completion use `Progress`.\n\n**Import:** `@/registry/erbium/ui/meter`\n\n```tsx\nimport { Meter, MeterLabel, MeterValue } from \"@/registry/erbium/ui/meter\";\n```\n\n## Base UI documentation\n\nExplore the underlying primitives and their API reference.\n\n- [Meter](https://base-ui.com/react/components/meter)",
      },
    },
  },
} satisfies Meta<typeof Meter>;

export default { ...meta, title: "Components/Meter",  decorators: [(Story, context) => <ShowcaseProviders toast={false && context.viewMode !== "docs"}><ShowcaseSurface><Story /></ShowcaseSurface></ShowcaseProviders>] } satisfies Meta;

type Story = StoryObj;

export const Playground: StoryObj<typeof Meter> = {
  args: { value: 24, min: 0, max: 100 },
  argTypes: {
    value: { control: { type: "range", min: 0, max: 100, step: 1 } },
    min: { control: "number" },
    max: { control: "number" },
  },
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: PlaygroundSource },
    },
  },
  render: PlaygroundExample,
};

export const Overview: Story = {
  parameters: {
    docs: {
      description: { story: "" },
      source: { code: OverviewSource },
    },
  },
  render: OverviewExample,
};

export const Range: Story = {
  parameters: {
    docs: {
      description: { story: "Set `min`, `max` and `format` to show the value in its own units." },
      source: { code: RangeSource },
    },
  },
  render: RangeExample,
};

import Demo from "../examples/meter-demo";

const Example = () => <Demo />;

export default Example;

import { Meter, MeterIndicator, MeterTrack } from "@/registry/erbium/ui/meter";
import type * as React from "react";

const Example = (args: React.ComponentProps<typeof Meter>) => (
  <Meter {...args} className="w-72" aria-label="Storage used">
    <MeterTrack>
      <MeterIndicator />
    </MeterTrack>
  </Meter>
);

export default Example;

import {
  Meter,
  MeterIndicator,
  MeterLabel,
  MeterTrack,
  MeterValue,
} from "@/registry/erbium/ui/meter";

const Example = () => (
  <Meter value={72} min={0} max={100} format={{ style: "unit", unit: "percent" }} className="w-72">
    <MeterLabel>Battery</MeterLabel>
    <MeterValue />
    <MeterTrack>
      <MeterIndicator />
    </MeterTrack>
  </Meter>
);

export default Example;

import { CSPProvider } from "@/registry/erbium/ui/csp-provider";
import { OverlayProvider } from "@/registry/erbium/ui/overlay-provider";
import { Toaster } from "@/registry/erbium/ui/toast";
import type { ReactNode } from "react";

export function ShowcaseProviders({
  children,
  toast = false,
}: {
  children?: ReactNode;
  toast?: boolean;
}) {
  return (
    <CSPProvider disableStyleElements>
      <OverlayProvider>
        {children}
        {toast && <Toaster />}
      </OverlayProvider>
    </CSPProvider>
  );
}

export function ShowcaseSurface({ children }: { children?: ReactNode }) {
  return (
    <div
      data-slot="component-preview"
      className="relative isolate mx-auto flex min-h-64 w-full min-w-0 max-w-3xl items-center justify-center gap-section p-5 font-sans text-foreground contain-layout sm:p-8 [&>.min-w-72.max-w-2xl]:flex [&>.min-w-72.max-w-2xl]:flex-col [&>.min-w-72.max-w-2xl]:items-center [&>.min-w-72.max-w-2xl]:justify-center"
    >
      {children}
    </div>
  );
}
